BEGIN;
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE castles (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, region VARCHAR(80) NOT NULL, house VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE lords (id BIGSERIAL PRIMARY KEY, telegram_user_id BIGINT NOT NULL UNIQUE, username VARCHAR(64), display_name VARCHAR(120) NOT NULL, castle_id BIGINT NOT NULL UNIQUE REFERENCES castles(id) ON DELETE RESTRICT, status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')), created_by_telegram_id BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE group_registrations (id BIGSERIAL PRIMARY KEY, telegram_chat_id BIGINT NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, chat_type VARCHAR(16) NOT NULL DEFAULT 'supergroup', castle_id BIGINT NOT NULL UNIQUE REFERENCES castles(id) ON DELETE RESTRICT, enabled BOOLEAN NOT NULL DEFAULT TRUE, registered_by_telegram_id BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE game_settings (key VARCHAR(100) PRIMARY KEY, value JSONB NOT NULL, updated_by_telegram_id BIGINT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE resource_balances (id BIGSERIAL PRIMARY KEY, lord_id BIGINT NOT NULL REFERENCES lords(id) ON DELETE RESTRICT, resource_code VARCHAR(50) NOT NULL, amount NUMERIC(24,4) NOT NULL DEFAULT 0 CHECK (amount >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(lord_id,resource_code));
CREATE TABLE castle_assets (id BIGSERIAL PRIMARY KEY, castle_id BIGINT NOT NULL REFERENCES castles(id) ON DELETE RESTRICT, asset_type VARCHAR(24) NOT NULL, asset_code VARCHAR(80) NOT NULL, level INTEGER NOT NULL DEFAULT 0, quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), UNIQUE(castle_id,asset_type,asset_code));
CREATE TABLE game_events (id BIGSERIAL PRIMARY KEY, event_type VARCHAR(80) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','completed','cancelled','failed')), payload JSONB NOT NULL DEFAULT '{}'::jsonb, idempotency_key VARCHAR(160) NOT NULL UNIQUE, due_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ);
CREATE INDEX ix_game_events_due ON game_events(status,due_at);
CREATE TABLE war_expeditions (id BIGSERIAL PRIMARY KEY, attacker_lord_id BIGINT NOT NULL REFERENCES lords(id) ON DELETE RESTRICT, origin_castle_id BIGINT NOT NULL REFERENCES castles(id) ON DELETE RESTRICT, target_castle_id BIGINT NOT NULL REFERENCES castles(id) ON DELETE RESTRICT, status VARCHAR(16) NOT NULL DEFAULT 'prepared' CHECK(status IN ('prepared','travelling','arrived','resolving','returning','completed','cancelled','failed')), units JSONB NOT NULL DEFAULT '{}'::jsonb, launched_at TIMESTAMPTZ, arrival_at TIMESTAMPTZ, return_at TIMESTAMPTZ, result JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_war_expeditions_status_arrival ON war_expeditions(status,arrival_at);
CREATE TABLE trade_offers (id BIGSERIAL PRIMARY KEY, sender_lord_id BIGINT NOT NULL REFERENCES lords(id) ON DELETE RESTRICT, recipient_lord_id BIGINT NOT NULL REFERENCES lords(id) ON DELETE RESTRICT, offered_resource VARCHAR(50) NOT NULL, offered_amount INTEGER NOT NULL CHECK(offered_amount>0), requested_resource VARCHAR(50) NOT NULL, requested_amount INTEGER NOT NULL CHECK(requested_amount>0), status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','cancelled','expired','completed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, CHECK(sender_lord_id<>recipient_lord_id));
CREATE INDEX ix_trade_offers_recipient_status ON trade_offers(recipient_lord_id,status);
CREATE TABLE admin_audit_logs (id BIGSERIAL PRIMARY KEY, actor_telegram_id BIGINT NOT NULL, action VARCHAR(100) NOT NULL, target_type VARCHAR(80), target_id VARCHAR(120), reason TEXT, details TEXT, before_value JSONB, after_value JSONB, correlation_id VARCHAR(80), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_admin_audit_logs_created ON admin_audit_logs(created_at);
CREATE TABLE game_state (key VARCHAR(80) PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO schema_version(version) VALUES (1) ON CONFLICT DO NOTHING;
COMMIT;
